// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testRegression_property() public {
        c.initialize(
            address(0),
            address(0x1234),
            100e18,
            10e18,
            0,
            500,
            bytes32(0),
            false,
            false
        );

        bool secondInitSucceeded;
        try c.initialize(
            address(0),
            address(0x1234),
            200e18,
            20e18,
            0,
            1000,
            bytes32(0),
            false,
            false
        ) {
            secondInitSucceeded = true;
        } catch {
            secondInitSucceeded = false;
        }

        assertTrue(!secondInitSucceeded || c.initialized() == false);
    }
}
